// План specs/pricebook.md 1.3 (кейс .qa/tests/pricebook/PB-03). Pre-Prod, preprod-ttp (TTP Test Locks), десктоп, EN.
// @writes @data: счёт «QA-AUTO pb-inv #df9bec …» (клиент TTP Customer) с позицией «QA-AUTO pb-inv-line …»; в конце — Actions → Delete.
import { test, expect } from '../../fixtures';
import {
  ROLE, addManualItem, expectNotInPriceBook, itemRow, openNewInvoice, openPriceBook, priceBookTotal, removeDocumentAt, removeFromList, setInvoiceName, stamp, watchPriceBookWrites,
} from './pricebook-helpers';

test.describe('Price Book — только ручные позиции (#df9bec)', () => {
  test('QA-AUTO: item typed in a new invoice stays only in the invoice, not added to Price Book #df9bec @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(150_000);
    const page = await asUser(ROLE);
    const s = stamp();
    const title = `QA-AUTO pb-inv #df9bec ${s}`;
    const item = { name: `QA-AUTO pb-inv-line ${s}`, price: '1' };
    let invoiceUrl: string | null = null;
    try {
      // Шаг 1: Total Items до
      await openPriceBook(page);
      const before = await priceBookTotal(page);

      // Шаги 2–4: New Invoice → Bill To → Add Item → Create Invoice
      const writes = watchPriceBookWrites(page);
      await openNewInvoice(page);
      await setInvoiceName(page, title);
      await addManualItem(page, item);
      await expect(itemRow(page, item.name)).toHaveCount(1);
      invoiceUrl = page.url();
      await page.getByRole('button', { name: 'Create Invoice' }).click();
      await expect(page.getByRole('button', { name: 'Create Invoice' })).toHaveCount(0, { timeout: 20_000 });
      await expect(itemRow(page, item.name)).toHaveCount(1);
      invoiceUrl = page.url();
      expect(writes, 'POST/PATCH/PUT к PriceBook при добавлении позиции и создании счёта').toEqual([]);

      // Шаг 5: Price Book — число позиций то же, поиск пуст (источник: «מה רצוי» — או עבודה/חשבונית)
      await expectNotInPriceBook(page, item.name, before);
      expect(writes, 'запросов записи в PriceBook нет').toEqual([]);
    } finally {
      await removeDocumentAt(page, invoiceUrl, title);
      await removeFromList(page, '/invoices', title);
    }
  });
});
